"use strict";const COOKIE_BAR_MAX_RETRIES=2,COOKIE_BAR_DEFAULT_RETRY_AFTER_SECONDS=5,COOKIE_BAR_RETRY_MARGIN_MS=1e3;class CookieStatusError extends Error{constructor(t,s){super(`Cookie consent status request failed with HTTP ${t}.`),this.name="CookieStatusError",this.status=t,this.retryAfterSeconds=s}}function parseRetryAfter(o){const t=Number.parseInt(o,10);return Number.isFinite(t)&&t>=0?t:5}function guardCookieStatusFetch(o){const t=window.fetch;window.fetch=async(s,n)=>{const e=await t(s,n);if(s===o&&!e.ok)throw new CookieStatusError(e.status,parseRetryAfter(e.headers.get("Retry-After")));return e}}function startCookieBar(o,t){guardCookieStatusFetch(t.statusUrl);let s=0;const n=()=>Promise.resolve().then(()=>o(t)).catch(e=>{const r=e instanceof CookieStatusError&&e.status===429;if(r&&s<2){s+=1;const i=e.retryAfterSeconds*1e3+1e3;return new Promise(c=>{window.setTimeout(()=>c(n()),i)})}r?console.warn("Cookie consent status could not be loaded.",e):console.error("Cookie consent bar could not be shown.",e)});return n()}window.startCookieBar=startCookieBar;
